// v64: homework plan (pure, unit-tested, no AI). The chosen TIME decides the amount of work, the LEVEL decides the
// kind of work, the student's own data decides the topics (40% recent, 30% weak points, 20% earlier grammar, 10%
// vocabulary). Each block is generated by its own small AI call (no truncated answers, retries per block).
// v66 focus options: auto (personalised 40/30/20/10), last_lesson, mix (everything evenly), developing (topics in
// progress / to review), choose (teacher picks topics from the learning line). Older values stay accepted.
import {templateFor, itemProblem} from './templates.ts';
// v68: 'lesson' = the topics selected / covered for the latest lesson (lesson_goals), only that grammar
export type Focus = 'auto' | 'last_lesson' | 'mix' | 'developing' | 'choose' | 'lesson' | 'weak' | 'review' | 'vocab' | 'topics';
export type Role = 'recent' | 'weak' | 'review' | 'vocab' | 'reading' | 'writing';
export type BlockType = 'conjugate' | 'fill_in' | 'multiple_choice' | 'translate' | 'correct_error' | 'make_sentence' | 'transform' | 'reading' | 'write';
export type Block = {i: number; role: Role; type: BlockType; count: number; weight: number; topic?: string; open: boolean};

const LV = ['A0', 'A1', 'A2', 'B1', 'B2', 'C1', 'C2'];
export const levelIdx = (l: string) => Math.max(0, LV.indexOf(String(l || '').toUpperCase()));
/** Minutes → number of blocks ("oefenblokken"): 5→1, 10→2, 15→3, 20→4, 30→6, 45→8. */
export function blocksFor(minutes: number) {
  const m = Math.max(5, Math.min(60, Math.round(minutes || 10)));
  return m <= 5 ? 1 : m <= 10 ? 2 : m <= 15 ? 3 : m <= 20 ? 4 : m <= 30 ? 6 : 8;
}
/** Closed-exercise types per level (examples; the student's own topics decide the content). */
const TYPES: Record<string, BlockType[]> = {
  A: ['conjugate', 'fill_in', 'multiple_choice', 'make_sentence', 'translate'],
  A2: ['fill_in', 'conjugate', 'correct_error', 'make_sentence', 'multiple_choice', 'transform'],
  B1: ['correct_error', 'transform', 'fill_in', 'make_sentence', 'multiple_choice'],
  B2: ['transform', 'correct_error', 'make_sentence', 'fill_in'],
  C: ['transform', 'correct_error', 'make_sentence'],
};
const typesFor = (level: string) => { const k = levelIdx(level); return TYPES[k <= 1 ? 'A' : k === 2 ? 'A2' : k === 3 ? 'B1' : k === 4 ? 'B2' : 'C']; };
/** Reading text length (words) per level and available time. */
export function textLength(level: string, minutes: number): [number, number] {
  const k = levelIdx(level), short = minutes < 20;
  const r: [number, number] = k <= 2 ? [80, 150] : k === 3 ? [150, 250] : k === 4 ? [200, 350] : [250, 450];
  return short ? [Math.round(r[0] * 0.7), Math.round(r[1] * 0.6)] : r;
}
const ROLE_W: [Role, number][] = [['recent', 0.4], ['weak', 0.3], ['review', 0.2], ['vocab', 0.1]];
/** Largest-remainder split of n blocks over the roles (40/30/20/10). */
export function splitRoles(n: number): Role[] {
  if (n <= 0) return [];
  const raw = ROLE_W.map(([r, w]) => ({r, x: w * n})), out = raw.map(o => ({r: o.r, k: Math.floor(o.x), rem: o.x - Math.floor(o.x)}));
  let left = n - out.reduce((s, o) => s + o.k, 0);
  for (const o of [...out].sort((a, b) => b.rem - a.rem)) { if (left <= 0) break; o.k++; left--; }
  // interleave so the order of the homework varies (recent, weak, review, recent, …)
  const res: Role[] = []; for (let i = 0; res.length < n; i++) for (const o of out) if (o.k > i) res.push(o.r);
  return res.slice(0, n);
}

export function planBlocks(minutes: number, level: string, focus: Focus = 'auto', opts: {skipReading?: boolean} = {}): Block[] {
  let n = blocksFor(minutes); const k = levelIdx(level), blocks: Block[] = [];
  // from A2: 15+ min → a reading or writing component; 20+ min → a reading text with open questions (counts as 2 blocks)
  if (k >= 2 && minutes >= 20 && !opts.skipReading && focus !== 'vocab') { blocks.push({i: 0, role: 'reading', type: 'reading', count: Math.min(5, 3 + Math.floor((minutes - 20) / 15)), weight: 2, open: true}); n -= 2; }
  if (k >= 2 && minutes >= 15 && !opts.skipReading && focus !== 'vocab' && (minutes < 20 || minutes >= 30)) { blocks.push({i: 0, role: 'writing', type: 'write', count: 1, weight: 2, open: true}); n -= 2; }
  n = Math.max(1, n);
  const MIX: Role[] = ['recent', 'review', 'weak', 'vocab'];
  const roles: Role[] = focus === 'last_lesson' ? Array(n).fill('recent') : focus === 'weak' || focus === 'developing' ? Array(n).fill('weak') : focus === 'review' ? Array(n).fill('review')
    : focus === 'vocab' ? Array(n).fill('vocab') : focus === 'topics' || focus === 'choose' || focus === 'lesson' ? Array(n).fill('recent') : focus === 'mix' ? Array.from({length: n}, (_, j) => MIX[j % 4]) : splitRoles(n);
  const types = typesFor(level);
  roles.forEach((role, j) => {
    const type: BlockType = role === 'vocab' ? (j % 2 ? 'translate' : 'fill_in') : types[j % types.length];
    const open = type === 'make_sentence' || type === 'transform';
    blocks.push({i: 0, role, type, count: open ? 4 : 5, weight: 1, open});
  });
  // closed blocks first, then reading/writing at the end
  return [...blocks.filter(b => b.weight === 1), ...blocks.filter(b => b.weight > 1)].map((b, i) => ({...b, i}));
}

/** Topics per block from the student's own lists; no topic twice while others are available; never invented
 *  grammar: an empty list falls back to the next list, and finally to the student's vocabulary. */
export function assignTopics(blocks: Block[], c: {recent: string[]; weak: string[]; review: string[]; topics?: string[]}, seed = 1): Block[] {
  const lists: Record<string, string[]> = {recent: c.topics?.length ? c.topics : c.recent, weak: c.weak, review: c.review};
  const used = new Set<string>(); let s = seed >>> 0; const rnd = () => ((s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 4294967296);
  const pick = (order: string[]) => {
    for (const key of order) { const l = (lists[key] || []).filter(Boolean); const fresh = l.filter(t => !used.has(t)); const from = fresh.length ? fresh : l;
      if (from.length) { const t = from[Math.floor(rnd() * Math.min(from.length, 3))]; used.add(t); return t; } }
    return undefined;
  };
  return blocks.map(b => {
    if (b.role === 'vocab') return b;
    if (b.role === 'reading' || b.role === 'writing') return {...b, topic: pick(['recent', 'weak', 'review'])};
    const order = b.role === 'weak' ? ['weak', 'recent', 'review'] : b.role === 'review' ? ['review', 'weak', 'recent'] : ['recent', 'weak', 'review'];
    const topic = pick(order);
    return topic ? {...b, topic} : {...b, role: 'vocab', type: b.open ? 'make_sentence' : 'fill_in'};
  });
}

/** v66: a grammar block takes the exercise form of its topic's template (e.g. perfectum → conjugate in a story,
 *  bijzin → combine sentences) so the form fits the learning goal; vocabulary/reading/writing blocks keep theirs. */
export function applyTemplates(blocks: Block[]): Block[] {
  return blocks.map(b => {
    if (!b.topic || b.role === 'vocab' || b.type === 'reading' || b.type === 'write') return b;
    const t = templateFor(b.topic); if (t.id === 'generic') return b;
    const open = t.type === 'make_sentence';
    return {...b, type: t.type, open, count: open ? 4 : 5};
  });
}

/** v66: drop items that break the quality rules (answer in brackets, ambiguous options, duplicates …). */
export function cleanItems<T extends GenItem>(items: T[], open = false): {kept: T[]; dropped: {item: T; why: string}[]} {
  const kept: T[] = [], dropped: {item: T; why: string}[] = [], seen = new Set<string>();
  for (const it of items) {
    const key = String(it.prompt || '').trim().toLowerCase();
    const why = seen.has(key) ? 'dubbel' : itemProblem({...it, options: it.options || []}, {open});
    if (why) dropped.push({item: it, why}); else { kept.push(it); seen.add(key); }
  }
  return {kept, dropped};
}

/** A generated block is usable only when complete: enough items, every prompt and answer filled, gaps/options
 *  consistent, a real reading text. Otherwise it is generated again (never published half). */
export type GenItem = {type: string; prompt: string; options: string[]; answer: string};
export function validBlock(b: {items: GenItem[]; passage: string} | null | undefined, spec: Pick<Block, 'count' | 'type'>): boolean {
  if (!b || !Array.isArray(b.items) || b.items.length < Math.max(1, Math.ceil(spec.count * 0.6))) return false;
  if (spec.type === 'reading' && String(b.passage || '').trim().split(/\s+/).length < 40) return false;
  return b.items.every(it => String(it.prompt || '').trim().length > 2 && String(it.answer || '').trim() !== '' && (it.type !== 'multiple_choice' || (it.options.length >= 2 && it.options.includes(it.answer))) && (it.type !== 'fill_in' || /_{2,}|…/.test(it.prompt)));
}
